class Solution {
    public int[][] colorBorder(int[][] grid,int row,int col,int color){
        boolean[][] visited=new boolean[grid.length][grid[0].length];
        List<int[]> borders=new ArrayList<>();
        dfs(grid,row,col,grid[row][col],visited,borders);
        for(int[] cell:borders)grid[cell[0]][cell[1]]=color;
        return grid;
    }
    private void dfs(int[][] grid,int r,int c,int original,boolean[][] visited,List<int[]> borders){
        visited[r][c]=true;
        boolean border=false;
        int[][] directions={
            {
                1,0
            },{
                -1,0
            },{
                0,1
            },{
                0,-1
            }
        };
        for(int[] d:directions){
            int nr=r+d[0],nc=c+d[1];
            if(nr<0||nr==grid.length||nc<0||nc==grid[0].length||grid[nr][nc]!=original)border=true;
            else if(!visited[nr][nc])dfs(grid,nr,nc,original,visited,borders);
        }
        if(border)borders.add(new int[]{
            r,c
        });
    }
}

code.kotlin:
class Solution {
    fun colorBorder(grid:Array<IntArray>,row:Int,col:Int,color:Int):Array<IntArray>{
        val visited=Array(grid.size){
            BooleanArray(grid[0].size)
        };
        val borders=mutableListOf<IntArray>();
        val original=grid[row][col];
        fun dfs(r:Int,c:Int){
            visited[r][c]=true;
            var border=false;
            val directions=arrayOf(intArrayOf(1,0),intArrayOf(-1,0),intArrayOf(0,1),intArrayOf(0,-1));
            for(d in directions){
                val nr=r+d[0];
                val nc=c+d[1];
                if(nr !in grid.indices||nc !in grid[0].indices||grid[nr][nc]!=original)border=true else if(!visited[nr][nc])dfs(nr,nc)
            };
            if(border)borders.add(intArrayOf(r,c))
        };
        dfs(row,col);
        for(cell in borders)grid[cell[0]][cell[1]]=color;
        return grid
    }
}

